"""rad0040 (VTP44): the packed KV layouts as one table. rad_builder.h's RAD_KV_LAYOUTS (id, --kv-cache-dtype name, row bytes per
16 dims, scale group) generates the RAD_KVQ_* enum and the name, parse and row-size functions that the flag parser, the
core and the Qwen3.5 FP8 plugin read instead of their own lists; libr4d's bf16_fp8 and bf16_i8 attention rows (constraints,
names, descriptions) are generated from one tuple list, with a compile-time check that a tuple names a table layout.
No behaviour change: the rows object is byte-identical.
"""
from __future__ import annotations

import re
from bigcherry.patcher import Edit, FilePatch


def _edit(id: str, before: str, after: str, guard: str) -> Edit:
    span = max(4, before.count("\n") + 2)
    return Edit(id=id, anchor=re.escape(before), mode="replace", text=after,
                guard=re.escape(guard), expect_matches=1, max_span_lines=span,
                rationale=("long-anchor: the whole diff hunk is the anchor; " if span > 6 else "")
                + "VTP44: KV layout table")


