        _edit('rad_builder_h-1', " * Codes are two's complement (int4 -7..7, int6 -31..31, int8 -127..127). The group is declared at\n * RAD_F8E4M3 with head_dim the row's bytes / 2 so the core sizes pages from it; only the layout's\n * kernels read it. */\nenum {\n    RAD_KVQ_NONE = 0,\n    RAD_KVQ_V4   = 1,\n    RAD_KVQ_K6V4 = 2,\n    RAD_KVQ_B16F8 = 3,\n    RAD_KVQ_B16I8 = 4\n};\n\n/* RAD_KVQ_B16I8's group: the dims one V scale covers, a power of two from 8 to 32 and a divisor of\n * head_dim. A compile-time constant of the layout (the kernels, the stores and the plugin's row all\n * take it from here), and the row's bytes per 16 dims that follow from it: 49 at 32, 50 at 16. */\n#define RAD_KVQ_B16I8_GROUP 32\n#define RAD_KVQ_B16I8_ROW16 (48 + 32 / RAD_KVQ_B16I8_GROUP)\n\n/* The products of the prefill attention a deployment accepts in e4m3 (RadBuildCtx::\n * attn_prefill_fp8, `attn_paged`'s `prefill_fp8`): bits, so both is 3. */\nenum {\n", ' * Codes are two\'s complement (int4 -7..7, int6 -31..31, int8 -127..127). The group is declared at\n * RAD_F8E4M3 with head_dim the row\'s bytes / 2 so the core sizes pages from it; only the layout\'s\n * kernels read it. */\n/* RAD_KVQ_B16I8\'s group: the dims one V scale covers, a power of two from 8 to 32 and a divisor of\n * head_dim. A compile-time constant of the layout (the kernels, the stores and the plugin\'s row all\n * take it from here), and the row\'s bytes per 16 dims that follow from it: 49 at 32, 50 at 16. */\n#define RAD_KVQ_B16I8_GROUP 32\n#define RAD_KVQ_B16I8_ROW16 (48 + 32 / RAD_KVQ_B16I8_GROUP)\n\n/* The packed KV layouts, the one list the engine reads: the --kv-cache-dtype spelling, the enum, the\n * row\'s size and the scale group all come from it, so a new layout is one line here (plus its kernels)\n * and no name list elsewhere needs editing. X(id, name, row16, group):\n *   id     the suffix of RAD_KVQ_<id>; the order is the enum\'s value, so only append\n *   name   the --kv-cache-dtype value, and the kv_dtype an `attn_paged` op\'s rows band on\n *   row16  the bytes a token\'s row holds per 16 dims of head_dim (plain bf16 is 32, E4M3 16)\n *   group  the dims one scale covers, 0 for a layout with no scales\n * The byte layout of each is documented above; this table holds the sizes only. */\n#define RAD_KV_LAYOUTS(X) \\\n    X(V4,    "fp8_v4",   25, 32) \\\n    X(K6V4,  "k6_v4",    22, 32) \\\n    X(B16F8, "bf16_fp8", 48, 0) \\\n    X(B16I8, "bf16_i8",  RAD_KVQ_B16I8_ROW16, RAD_KVQ_B16I8_GROUP)\n\nenum {\n    RAD_KVQ_NONE = 0,\n#define RAD_KV_LAYOUT_ENUM(id, name, row16, group) RAD_KVQ_##id,\n    RAD_KV_LAYOUTS(RAD_KV_LAYOUT_ENUM)\n#undef RAD_KV_LAYOUT_ENUM\n    RAD_KVQ_COUNT   /* one past the last layout */\n};\n\n/* The --kv-cache-dtype name of a RAD_KVQ_* layout, or NULL for RAD_KVQ_NONE and an unknown value. */\nstatic inline const char* rad_kvq_name(int kvq) {\n    switch (kvq) {\n#define RAD_KV_LAYOUT_NAME(id, name, row16, group) case RAD_KVQ_##id: return name;\n    RAD_KV_LAYOUTS(RAD_KV_LAYOUT_NAME)\n#undef RAD_KV_LAYOUT_NAME\n    default: return 0;\n    }\n}\n\n/* The RAD_KVQ_* layout a --kv-cache-dtype name asks for; RAD_KVQ_NONE for any other name (bf16 and fp8\n * are plain caches). */\nstatic inline int rad_kvq_from_name(const char* n) {\n    if (!n) return RAD_KVQ_NONE;\n#define RAD_KV_LAYOUT_FIND(id, name, row16, group) if (!strcmp(n, name)) return RAD_KVQ_##id;\n    RAD_KV_LAYOUTS(RAD_KV_LAYOUT_FIND)\n#undef RAD_KV_LAYOUT_FIND\n    return RAD_KVQ_NONE;\n}\n\n/* The bytes a token\'s row holds per 16 dims of head_dim: the table\'s row16, 32 for RAD_KVQ_NONE (the\n * plain 2-byte cache) and 0 for an unknown value. A row is head_dim * row16 / 16 bytes. */\nstatic inline int rad_kvq_row16(int kvq) {\n    if (kvq == RAD_KVQ_NONE) return 32;\n    switch (kvq) {\n#define RAD_KV_LAYOUT_ROW(id, name, row16, group) case RAD_KVQ_##id: return row16;\n    RAD_KV_LAYOUTS(RAD_KV_LAYOUT_ROW)\n#undef RAD_KV_LAYOUT_ROW\n    default: return 0;\n    }\n}\n\n/* The layouts\' names as one " | a | b | c" string literal, for a help line or an error message. */\n#define RAD_KV_LAYOUT_NAME_LIST_(id, name, row16, group) " | " name\n#define RAD_KV_LAYOUT_NAMES RAD_KV_LAYOUTS(RAD_KV_LAYOUT_NAME_LIST_)\n\n/* The products of the prefill attention a deployment accepts in e4m3 (RadBuildCtx::\n * attn_prefill_fp8, `attn_paged`\'s `prefill_fp8`): bits, so both is 3. */\nenum {\n', '/* The packed KV layouts, the one list the engine reads: the --kv-cache-dtype spelling, the enum, the'),
