        _edit('rad_core_h-0', '/* The RadBuildCtx::kv_quant layout a --kv-cache-dtype name asks for: RAD_KVQ_NONE for bf16 and fp8,\n * which are plain caches. The one list of packed layouts\' names (rad_builder.h). */\ninline int bc_kv_quant_of(const std::string& kv_cache_dtype) {\n    return kv_cache_dtype == "fp8_v4"   ? RAD_KVQ_V4\n         : kv_cache_dtype == "k6_v4"    ? RAD_KVQ_K6V4\n         : kv_cache_dtype == "bf16_fp8" ? RAD_KVQ_B16F8\n         : kv_cache_dtype == "bf16_i8"  ? RAD_KVQ_B16I8 : RAD_KVQ_NONE;\n}\n\n}  /* namespace rad */\n', "/* The RadBuildCtx::kv_quant layout a --kv-cache-dtype name asks for: RAD_KVQ_NONE for bf16 and fp8,\n * which are plain caches. The one list of packed layouts' names (rad_builder.h). */\ninline int bc_kv_quant_of(const std::string& kv_cache_dtype) {\n    return rad_kvq_from_name(kv_cache_dtype.c_str());\n}\n\n}  /* namespace rad */\n", 'return rad_kvq_from_name(kv_cache_dtype.c_str());'),
